package com.xjtu.iron.idempotent.demo;
import com.xjtu.iron.idempotent.api.*;import org.springframework.web.bind.annotation.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Duration;import java.util.HexFormat;
@RestController @RequestMapping("/demo/idempotency") public class IdempotencyDemoController{private final IdempotencyExecutor executor;public IdempotencyDemoController(IdempotencyExecutor executor){this.executor=executor;}
 @PostMapping("/short-term/{key}") public IdempotencyResult<String> shortTerm(@PathVariable String key,@RequestParam(defaultValue="payload")String payload){IdempotencyOptions o=IdempotencyOptions.builder().mode(IdempotencyMode.SHORT_TERM).processingTimeout(Duration.ofSeconds(10)).recordTtl(Duration.ofMinutes(5)).storeResult(true).build();IdempotencyRequest r=IdempotencyRequest.builder().key(key).requestHash(sha(payload)).options(o).build();return executor.execute(r,String.class,c->"short-term executed, version="+c.getVersion()+", payload="+payload);}
 @PostMapping("/durable/{key}") public IdempotencyResult<String> durable(@PathVariable String key,@RequestParam(defaultValue="payload")String payload){IdempotencyOptions o=IdempotencyOptions.builder().mode(IdempotencyMode.DURABLE).processingTimeout(Duration.ofSeconds(30)).storeResult(true).build();IdempotencyRequest r=IdempotencyRequest.builder().key(key).requestHash(sha(payload)).options(o).build();return executor.execute(r,String.class,c->"durable executed, fencingVersion="+c.fencingVersion()+", payload="+payload);}
 private String sha(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
